const input = $input.first().json ?? {};

// إذا كانت البيانات داخل الغلاف التشخيصي، نستخرجها
const source = input.receivedData ?? input;

// البحث عن نص إجابة AI Agent داخل البيانات المتداخلة
function findAIText(obj, depth = 0) {
  if (depth > 8 || obj == null) return null;

  if (typeof obj === "string") {
    return obj.trim() ? obj : null;
  }

  if (Array.isArray(obj)) {
    for (const value of obj) {
      const found = findAIText(value, depth + 1);
      if (found) return found;
    }
    return null;
  }

  if (typeof obj === "object") {
    const preferredKeys = [
      "output", "text", "response", "content",
      "answer", "result", "message"
    ];

    for (const key of preferredKeys) {
      if (obj[key] !== undefined) {
        const found = findAIText(obj[key], depth + 1);
        if (found) return found;
      }
    }

    for (const value of Object.values(obj)) {
      const found = findAIText(value, depth + 1);
      if (found) return found;
    }
  }

  return null;
}

const raw = findAIText(source);

if (!raw) {
  throw new Error(
    "No AI text found. Received data: " +
    JSON.stringify(source).slice(0, 3000)
  );
}

// تنظيف النص
const cleaned = raw
  .replace(/^\uFEFF/, "")
  .replace(/```(?:json)?/gi, "")
  .replace(/```/g, "")
  .trim();

const start = cleaned.indexOf("{");
const end = cleaned.lastIndexOf("}");

if (start === -1 || end <= start) {
  throw new Error(
    "AI did not return a JSON object. Response: " +
    cleaned.slice(0, 3000)
  );
}

let result;

try {
  result = JSON.parse(cleaned.slice(start, end + 1));
} catch (error) {
  throw new Error(
    "Invalid AI JSON: " + error.message +
    "\nResponse: " + cleaned.slice(0, 3000)
  );
}

// التحقق من البيانات
if (
  !result.title ||
  !Array.isArray(result.slides) ||
  result.slides.length === 0
) {
  throw new Error("Presentation must contain a title and non-empty slides array.");
}

// تجهيز البيانات لخدمة PowerPoint
const slides = result.slides.map((slide, index) => {
  const bullets = Array.isArray(slide.bullets)
    ? slide.bullets.map(v => String(v).trim()).filter(Boolean)
    : [];

  if (!bullets.length) {
    throw new Error(
      "Slide " + (index + 1) + " has no bullet content."
    );
  }

  return {
    title: String(slide.title || `Slide ${index + 1}`),
    bullets,
    example: String(slide.example || "")
  };
});

return [{
  json: {
    title: String(result.title),
    subtitle: String(result.subtitle || ""),
    slides
  }
}];
